const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point([114.26, 30.60]).buffer(3000); // Jianghan District, Wuhan, with a 3km buffer
  const date1 = '2020-01-19';
  const date2 = '2020-02-04';
  const band = 'DNB_BRDF_Corrected_NTL';

  // 2. Data Acquisition Function
  const getDataForDate = function(dateString) {
    const start = ee.Date(dateString);
    const end = start.advance(1, 'day');
    const collection = ee.ImageCollection('NOAA/VIIRS/DNB/VNP46A1')
      .filterDate(start, end)
      .filterBounds(geometry);
    return collection;
  };

  const collection1 = getDataForDate(date1);
  const collection2 = getDataForDate(date2);

  // 3. Initial Data Checks
  const count1 = collection1.size().getInfo();
  const count2 = collection2.size().getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Image count for ${date1}: ${count1}`);
    console.log(`Image count for ${date2}: ${count2}`);
    console.log('Evidence: No image found for one or both dates.');
    console.log('A: No');
    console.log('B: No');
    console.log('C1: Yes');
    console.log('C2: No');
    console.log('C3: No');
    console.log('D: No');
    console.log('C1');
    return;
  }

  // 4. Processing & Calculation
  // Cloud masking function: 0 = Confident Clear
  const maskClouds = function(image) {
    const cloudMask = image.select('QF_Cloud_Mask').eq(0);
    return image.updateMask(cloudMask);
  };

  const image1 = ee.Image(collection1.first()).select(band).updateMask(ee.Image(1)); // Start with a full mask
  const image2 = ee.Image(collection2.first()).select(band).updateMask(ee.Image(1));

  // Mask clouds and other low-quality data
  const image1_masked = maskClouds(image1);
  const image2_masked = maskClouds(image2);

  const options = {
    reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    }),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  };

  const stats1 = image1_masked.reduceRegion(options).getInfo();
  const stats2 = image2_masked.reduceRegion(options).getInfo();

  const mean1 = stats1 ? stats1[band+'_mean'] : null;
  const pixels1 = stats1 ? stats1[band+'_count'] : 0;
  const mean2 = stats2 ? stats2[band+'_mean'] : null;
  const pixels2 = stats2 ? stats2[band+'_count'] : 0;

  // 5. Validation & Final Answer
  console.log(`${date1} (Jan 19) Avg Light: ${mean1 ? mean1.toFixed(2) : 'N/A'}, Valid Pixels: ${pixels1}`);
  console.log(`${date2} (Feb 4) Avg Light: ${mean2 ? mean2.toFixed(2) : 'N/A'}, Valid Pixels: ${pixels2}`);

  if (pixels1 === 0 || pixels2 === 0) {
    console.log('Evidence: Zero valid (cloud-free) pixels in the area for at least one date.');
    console.log('A: No');
    console.log('B: No');
    console.log('C1: No');
    console.log('C2: Yes');
    console.log('C3: No');
    console.log('D: No');
    console.log('C2');
    return;
  }

  if (mean1 === null || mean2 === null) {
      console.log('Evidence: Calculation failed, resulting in a null value.');
      console.log('A: No');
      console.log('B: No');
      console.log('C1: No');
      console.log('C2: No');
      console.log('C3: Yes');
      console.log('D: No');
      console.log('C3');
      return;
  }

  if (mean2 < mean1) {
    console.log('Evidence: Nighttime light intensity was lower on Feb 4, 2020.');
    console.log('A: Yes');
    console.log('B: No');
    console.log('C1: No');
    console.log('C2: No');
    console.log('C3: No');
    console.log('D: No');
    console.log('A');
  } else {
    console.log('Evidence: Nighttime light intensity was NOT lower on Feb 4, 2020.');
    console.log('A: No');
    console.log('B: Yes');
    console.log('C1: No');
    console.log('C2: No');
    console.log('C3: No');
    console.log('D: No');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('Evidence: An error occurred during the analysis, likely related to GEE API, syntax, or memory.');
  console.log('A: No');
  console.log('B: No');
  console.log('C1: No');
  console.log('C2: No');
  console.log('C3: No');
  console.log('D: Yes');
  console.log('D');
});
